<template><div class="page-stack"><PageHeader title="家庭详情" description="家庭真实基础信息。"><el-button @click="$router.push(`/admin/families/${familyId}/members`)">查看成员</el-button></PageHeader><el-alert v-if="error" :title="error" type="error" show-icon/><section v-if="family" class="surface detail-card"><el-descriptions :column="4" border><el-descriptions-item label="家庭 ID">{{family.id}}</el-descriptions-item><el-descriptions-item label="名称">{{family.familyName}}</el-descriptions-item><el-descriptions-item label="姓氏">{{family.familySurname}}</el-descriptions-item><el-descriptions-item label="状态"><StatusTag :status="family.status"/></el-descriptions-item><el-descriptions-item label="籍贯">{{family.nativePlace||'未设置'}}</el-descriptions-item><el-descriptions-item label="地区">{{family.regionText||'未设置'}}</el-descriptions-item><el-descriptions-item label="公开状态"><StatusTag :status="family.publicDisplayStatus"/></el-descriptions-item><el-descriptions-item label="家谱版本">{{family.graphVersion}}</el-descriptions-item><el-descriptions-item label="成员数">{{family.memberCount}}</el-descriptions-item><el-descriptions-item label="允许搜索">{{family.searchable?'是':'否'}}</el-descriptions-item></el-descriptions><p>{{family.description||'未填写家庭简介'}}</p></section></div></template>
<script setup lang="ts">
import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{getApiErrorMessage}from'@/api/client';import{getFamily}from'@/api/management';import PageHeader from'@/components/PageHeader.vue';import StatusTag from'@/components/StatusTag.vue';import type{ManagedFamily}from'@/types/api';const route=useRoute(),familyId=String(route.params.familyId),family=ref<ManagedFamily|null>(null),error=ref('');onMounted(async()=>{try{family.value=await getFamily(familyId)}catch(e){error.value=getApiErrorMessage(e)}});
</script>
<style scoped>.detail-card{padding:16px}.detail-card p{color:var(--color-text-secondary);line-height:1.7}</style>
